#include "KS/SRC/beam.h"

bool beam_effect::handle_enx_chunk( chunk_file& fs, stringx& label )
{
  if(label == "alpha:")
    read_alpha_chunk(fs);
  else if(label == "width:")
    read_width_chunk(fs);
  else if(label == "color:")
    read_color_chunk(fs);
  else
    error( fs.get_filename() + ": unknown beam_effect type '" + label + "'" );

  return(true);
}
